const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Define Bobiri Forest Reserve geometry (approximate location in Ghana)
  const bobiri = ee.Geometry.Polygon([
    [[-1.35, 6.65], [-1.35, 6.75], [-1.25, 6.75], [-1.25, 6.65], [-1.35, 6.65]]
  ]);

  // 2. Load Hansen Global Forest Change dataset
  const hansen = ee.Image('UMD/hansen/global_forest_change_2023_v1_11');

  // 3. Get tree cover 2000 and loss year
  const treeCover2000 = hansen.select('treecover2000');
  const lossYear = hansen.select('lossyear');

  // Define forest as areas with >30% tree cover
  const forestMask2000 = treeCover2000.gte(30);

  // 4. Calculate forest for 2003 (losses from 2001-2003, which is year 1-3 in the dataset)
  const lossBy2003 = lossYear.gte(1).and(lossYear.lte(3));
  const forest2003 = forestMask2000.and(lossBy2003.not());

  // 5. Calculate forest for 2023 (losses from 2001-2023, which is year 1-23)
  const lossBy2023 = lossYear.gte(1).and(lossYear.lte(23));
  const forest2023 = forestMask2000.and(lossBy2023.not());

  // 6. Calculate forest area (pixel count) for both years
  const stats2003 = forest2003.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: bobiri,
    scale: 30,
    maxPixels: 1e9
  });

  const stats2023 = forest2023.reduceRegion({
    reducer: ee.Reducer.sum(),
    geometry: bobiri,
    scale: 30,
    maxPixels: 1e9
  });

  const forestPixels2003 = stats2003.get('treecover2000').getInfo();
  const forestPixels2023 = stats2023.get('treecover2000').getInfo();

  // 7. Check for valid data
  if (forestPixels2003 === null || forestPixels2023 === null) {
    console.log("Calculation returned null values.");
    console.log("<answer>C3</answer>");
    return;
  }

  if (forestPixels2003 === 0 && forestPixels2023 === 0) {
    console.log("No valid forest pixels found.");
    console.log("<answer>C2</answer>");
    return;
  }

  // 8. Calculate forest loss
  const forestLoss = forestPixels2003 - forestPixels2023;
  const percentChange = ((forestLoss / forestPixels2003) * 100).toFixed(2);

  // 9. Output results
  console.log(`Forest pixels 2003: ${forestPixels2003}`);
  console.log(`Forest pixels 2023: ${forestPixels2023}`);
  console.log(`Forest loss: ${forestLoss} pixels`);
  console.log(`Percent change: ${percentChange}%`);

  // 10. Final answer
  if (forestPixels2023 < forestPixels2003) {
    console.log("<answer>A</answer>");
  } else {
    console.log("<answer>B</answer>");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
